"""Build three bounded public defence-contract paths; no cash settlement inferred."""
import json,pathlib
B=pathlib.Path(__file__).resolve().parent
out={'sources':[],'entities':[],'relationships':[],'records':[],'localities':[]}
DOMAIN=['defence-trade','security','public-finance']
ROUTE='/defence-trade'
def geo(codes,src):
    return [{'scope':'country','countryCodes':codes,'stateCodes':[],'localityIds':[],'basis':'country-context','note':'Public contracting, supplier-country or intergovernmental context only; not beneficial ownership, cash destination or operational deployment.','sourceIds':src}]
def dim(src,codes,layers):
    return dict(domains=DOMAIN,layers=layers,geography=geo(codes,src),route=ROUTE,sourceIds=src,limitations=[])
def source(i,title,url,pub,date,locator,summary,tier='documented',limits=[]):
    out['sources'].append(dict(id=i,title=title,url=url,publisher=pub,publishedAt=date,retrievedAt='2026-10-07',locator=locator,summary=summary,tier=tier,limitations=limits))
def entity(i,label,typ,src,codes,summary,basis,canonical=None):
    row=dict(id=i,label=label,type=typ,resolved=True,identityBasis=basis,summary=summary,**dim(src,codes,['organisations']))
    if canonical:row['canonicalId']=canonical
    out['entities'].append(row)
def amount(v,c,u,s,p):return dict(value=v,currency=c,unit=u,stage=s,period=p)
def edge(i,a,b,kind,label,summary,src,codes,case,date=None,tier='documented',amounts=[],status='source-retained',limits=[],response=None):
    row=dict(id=i,**{'from':a,'to':b},kind=kind,label=label,summary=summary,tier=tier,status=status,statusAsOf=date,fromDate=None,toDate=None,dateBasis='Source/status date only unless an exact event date is separately stated; no one-day affiliation or continuing contract is inferred.',alternativeExplanations=['Ordinary public procurement, industrial participation or stated intergovernmental cooperation explains this link; no corruption or improper influence is asserted.'],falsifier='A corrected original contract, government release, manufacturer delivery ledger or legal-entity record contradicting the named parties or stage would require correction.',responseIds=[response] if response else [],recordIds=[case],amounts=amounts,**dim(src,codes,['procurement'] if kind not in ['jurisdiction','partner','member','agency'] else ['organisations']))
    row['limitations']=limits;out['relationships'].append(row);return row
def record(i,title,summary,src,codes,entities,edges,period,start,end,status,reply,limits,tier='documented',kind='investigation-case'):
    out['records'].append(dict(id=i,title=title,summary=summary,kind=kind,tier=tier,status=status,statusAsOf=end,fromDate=start,toDate=end,dateBasis='Exact dated events bound the investigation; undated corporate history and forecast dates are separately labelled. Publication date is not automatically an event date.',entityIds=entities,relationshipIds=edges,period=period,response=reply,alternativeExplanations=['These are disclosed procurement and industrial arrangements; a contract value is not evidence of a bribe, a supplier receipt or a public loss.'],falsifier='Original amendments, actual payment records or corrected delivery/acceptance documents could revise these stages; specific corruption requires separate decision/payment evidence.',amounts=[],**{**dim(src,codes,['procurement','funding','organisations']), 'limitations':limits}))

